#include "motor_control.h"
#include "PositionMotor.h"
#include "SpeedMotor.h"
#include "main.h"
#include <cstdio>

// Hardware handles generated by CubeMX
extern TIM_HandleTypeDef htim1; // PWM Timer (PA8)
extern TIM_HandleTypeDef htim5; // Encoder Timer (PA0/PA1)
extern I2C_HandleTypeDef hi2c1; // I2C Handle

// --- SWD Live Variables (Accessible via pyocd) ---
extern "C" {
    volatile float g_kp = 0.0f;         // Changed from 2.0f
    volatile float g_ki = 0.0f;         // Changed from 1.0f
    volatile float g_kd = 0.0f;
    volatile float g_target_rpm = 0.0f; // Changed from 30.0f (keeps motor stationary on boot)

    volatile float g_current_rpm = 0.0f;
    volatile float g_output_duty = 0.0f;

    volatile uint32_t g_raw_ticks = 0; // Exposed to pyOCD for live debugging
}

const float ELBOW_MIN_POS = 200.0f;
const float ELBOW_MAX_POS = 3800.0f;
#define AS5600_I2C_ADDR         (0x36 << 1)
#define AS5600_RAW_ANGLE_REG    0x0C

static float last_valid_position = 2048.0f;

// --- Speed Motor (PA8 PWM, PB2 & PB4 DIR) ---
static SpeedMotor driveMotor(&htim1, TIM_CHANNEL_1, 65535,
                              GPIOB, GPIO_PIN_2, GPIO_PIN_4,
                              2.0f, 1.0f, 0.0f);

static PositionMotor elbowMotor(&htim1, TIM_CHANNEL_1, 65535,
                                 GPIOB, GPIO_PIN_4,
                                 4095.0f,
                                 1.0f, 0.2f, 0.0f);

static float ReadElbowAbsolutePosition(void) {
    uint8_t buffer[2] = {0};

    HAL_StatusTypeDef status = HAL_I2C_Mem_Read(&hi2c1,
            AS5600_I2C_ADDR, AS5600_RAW_ANGLE_REG, I2C_MEMADD_SIZE_8BIT,
            buffer, 2, 2);

    if (status == HAL_OK) {
        uint16_t raw_val = ((uint16_t)buffer[0] << 8) | buffer[1];
        last_valid_position = (float)(raw_val & 0x0FFF);
    }

    return last_valid_position;
}

static float ReadDriveSpeedRPM(float dt_seconds) {
    static uint32_t prev_count = 0;

    // Read raw 32-bit hardware timer count
    uint32_t current_count = __HAL_TIM_GET_COUNTER(&htim5);
    g_raw_ticks = current_count; // Store raw tick value for SWD inspection

    int32_t delta_ticks = (int32_t)(current_count - prev_count);
    prev_count = current_count;

    const float ENCODER_PPR = 13.0f;
    const float GEAR_RATIO = 181.0f;
    const float ENCODER_MODE_MULT = 4.0f;
    const float TICKS_PER_REV = ENCODER_PPR * GEAR_RATIO * ENCODER_MODE_MULT;

    float revolutions = (float)delta_ticks / TICKS_PER_REV;
    return (revolutions / dt_seconds) * 60.0f;
}

void MotorControl_Init(void) {
    HAL_TIM_Encoder_Start(&htim5, TIM_CHANNEL_ALL);
    driveMotor.begin();
}

void Elbow_Control_Init(void) {
    elbowMotor.disableWrap();
    elbowMotor.begin();
}

void MotorControl_SetParams(float kp, float ki, float kd, float targetRpm) {
    driveMotor.setGains(kp, ki, kd);
    driveMotor.setTargetSpeed(targetRpm);
}

void MotorControl_Update(float dt_seconds) {
    driveMotor.setGains(g_kp, g_ki, g_kd);
    driveMotor.setTargetSpeed(g_target_rpm);

    g_current_rpm = ReadDriveSpeedRPM(dt_seconds);
    driveMotor.update(g_current_rpm, dt_seconds);

    g_output_duty = driveMotor.getOutput();
}

void Elbow_Control_Update(float target_position, float dt_seconds) {
	return;
    if (target_position > ELBOW_MAX_POS) target_position = ELBOW_MAX_POS;
    if (target_position < ELBOW_MIN_POS) target_position = ELBOW_MIN_POS;

    float current_position = ReadElbowAbsolutePosition();
    elbowMotor.setTargetPosition(target_position);
    elbowMotor.update(current_position, dt_seconds);
}
